<?php
require_once __DIR__.'/subscriptions.php';
if (!subscriptionOpsAllowed()) {
    http_response_code(403);
    echo '<section class="card"><h2>无法查看订阅订单</h2><p>需要成员敏感信息权限，请联系超级管理员。</p></section>';
    return;
}
$subscriptionNow = time();
$subscriptionEnvironment = subscriptionOpsEnvironment($config);
$subscriptionList = subscriptionOpsList($db, $_GET, $subscriptionNow);
$subscriptionUnlinked = subscriptionOpsUnlinkedEvents($db, (int)($_GET['unlinked_page'] ?? 1));
$subscriptionDetailID = max(0, (int)($_GET['user_id'] ?? 0));
$subscriptionDetail = $subscriptionDetailID ? subscriptionOpsDetail($db, $subscriptionDetailID, (int)($_GET['event_page'] ?? 1), $subscriptionNow) : null;
$subscriptionURL = static function (array $extra = []) use ($subscriptionList): string {
    return '?'.http_build_query(array_replace(['p'=>'subscriptions', 'q'=>$subscriptionList['search'], 'status'=>$subscriptionList['status'], 'environment'=>$subscriptionList['environment'], 'page'=>$subscriptionList['page']], $extra), '', '&', PHP_QUERY_RFC3986);
};
$subscriptionIssues = count(array_filter($subscriptionList['members'], static fn(array $row): bool => !$row['check']['consistent']));
?>
