<details class="advanced-settings"><summary>数据来源与核对范围</summary><p><?=h($subscriptionEnvironment['notice'])?></p><p class="muted">本页仅查询和比较，不会退款、补单或修改会员权益。金额缺失时显示“未留存”，不能据此推算收入；取消续订、退款撤销和自然到期分别判断。实时官方核验尚未接入本页，页面刷新不等于 Apple 验证。</p></details>
<form method="get" class="filters"><input type="hidden" name="p" value="subscriptions"><label>查找成员或交易<input name="q" value="<?=h($subscriptionList['search'])?>" maxlength="120" placeholder="成员编号、账号 ID、昵称、手机号、交易号"></label><label>筛选<select name="status"><?php foreach([''=>'全部有订阅/权益记录的成员','active'=>'当前权益有效','inactive'=>'当前权益无效','revoked'=>'曾有订阅被撤销','cancellation'=>'曾收到取消事件'] as $value=>$label):?><option value="<?=h($value)?>" <?=$subscriptionList['status']===$value?'selected':''?>><?=h($label)?></option><?php endforeach?></select></label><label>事件来源环境<select name="environment"><?php foreach([''=>'全部来源环境','PRODUCTION'=>'正式来源事件','SANDBOX'=>'沙盒来源事件','unknown'=>'环境未知的旧事件'] as $value=>$label):?><option value="<?=h($value)?>" <?=$subscriptionList['environment']===$value?'selected':''?>><?=h($label)?></option><?php endforeach?></select></label><button>查询</button></form>
<p class="muted">共 <?=safeNumber($subscriptionList['total'])?> 位成员，第 <?=$subscriptionList['page']?> 页，每页 25 位。本页 <?=safeNumber($subscriptionIssues)?> 位存在本地核对差异。环境筛选表示该成员曾收到该环境事件，不代表其全部订单属于该环境。</p>
<div class="table-wrap"><table><thead><tr><th>成员</th><th>当前权益</th><th>订单 / 赠送依据</th><th>本地核对</th><th>最近官方核验记录</th><th></th></tr></thead><tbody>
<?php foreach($subscriptionList['rows'] as $subscriptionUser):$subscriptionMember=$subscriptionList['members'][(int)$subscriptionUser['id']];$subscriptionCheck=$subscriptionMember['check'];$subscriptionActual=$subscriptionMember['actual'];$subscriptionSnapshot=$subscriptionMember['snapshot'];?>
<tr><td><strong><?=h($subscriptionUser['nickname']?:clubNumber((int)$subscriptionUser['id']))?></strong><small><?=h(clubNumber((int)$subscriptionUser['id']))?> · <?=h($subscriptionUser['phone']?:'无手机号')?></small><small>账号：<?=h(['active'=>'正常','disabled'=>'已禁用','deleted'=>'已注销'][$subscriptionUser['account_status']]??$subscriptionUser['account_status'])?></small></td>
<td><?=h(subscriptionOpsStatus($subscriptionActual,$subscriptionNow))?><small><?=h(($subscriptionActual['source']??'')==='admin'?'运营赠送':(($subscriptionActual['source']??'')==='apple'?'Apple 购买':'—'))?></small><small><?=h(subscriptionOpsDate($subscriptionActual['expires_at']??null))?></small></td>
<td><?=count($subscriptionMember['subscriptions'])?> 条订阅投影<small><?=h($subscriptionCheck['basis'])?></small><small><?=h($subscriptionCheck['expected_active']?'本地依据有效':'本地依据当前无效')?></small></td>
<td><span class="badge"><?=h($subscriptionCheck['consistent']?'本地一致':'需要核对')?></span><?php foreach($subscriptionCheck['issues'] as $issue):?><small><?=h($issue)?></small><?php endforeach?></td>
<td><?=h(subscriptionOpsDate($subscriptionSnapshot['verified_at']??null))?><small><?=h(['active'=>'有效','inactive'=>'无效'][$subscriptionSnapshot['verified_status']??'']??'未核验')?></small><?php if(!empty($subscriptionSnapshot['last_error_code'])):?><small>最近尝试失败：<?=h($subscriptionSnapshot['last_error_code'])?></small><?php endif?></td>
